package com.rotarypumpers.meraki;
import android.content.Context;import android.graphics.*;import android.view.View;import org.json.*;
/** Small scale-weight trace. Keeps gaps and clips at brew stop. */
final class ShotSparkline extends View {
 private final JSONObject shot;private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);
 ShotSparkline(Context context,JSONObject shot){super(context);this.shot=shot;setContentDescription("Recorded scale weight; amber dashes indicate missing data");}
 protected void onDraw(Canvas c){super.onDraw(c);JSONArray rows=shot.optJSONArray("samples");if(rows==null||rows.length()<2)return;double first=rows.optJSONObject(0).optDouble("uptime"),last=rows.optJSONObject(rows.length()-1).optDouble("uptime");double start=ReplayTimeline.bound(shot,"start_bounds",first),end=Math.min(last,ReplayTimeline.bound(shot,"stop_bounds",last));if(end<=start)return;double max=1;for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r.optDouble("uptime")<=end&&Double.isFinite(r.optDouble("weight_g")))max=Math.max(max,r.optDouble("weight_g"));}float d=getResources().getDisplayMetrics().density;JSONObject recipe=shot.optJSONObject("recipe");double target=recipe==null?Double.NaN:recipe.optDouble("time_s"),targetMax=recipe==null?Double.NaN:recipe.optDouble("time_max_s",target);double extent=Math.max(end-start,Double.isFinite(targetMax)?targetMax:0);if(Double.isFinite(target)&&target>0&&targetMax>=target){paint.setStyle(Paint.Style.FILL);paint.setColor(0x25a9c397);float x1=(float)(2*d+(getWidth()-4*d)*target/extent),x2=(float)(2*d+(getWidth()-4*d)*targetMax/extent);c.drawRect(x1,0,Math.max(x1+d,x2),getHeight(),paint);}Path path=new Path(),gaps=new Path();float priorX=0,priorY=0;boolean begun=false;double previous=Double.NaN;for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);double t=r.optDouble("uptime"),v=r.optDouble("weight_g");if(t<start)continue;if(t>end)break;if(!Double.isFinite(v)){begun=false;continue;}float x=(float)((getWidth()-4*d)*(t-start)/extent+2*d),y=(float)(getHeight()-3*d-Math.max(0,v)/max*(getHeight()-6*d));if(!begun||t-previous>ReplayTimeline.gapLimit(shot)){if(begun){gaps.moveTo(priorX,priorY);gaps.lineTo(x,y);}path.moveTo(x,y);}else path.lineTo(x,y);begun=true;previous=t;priorX=x;priorY=y;}paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(1.5f*d);paint.setColor(0xffefb48d);c.drawPath(path,paint);paint.setColor(0xffe8bb7c);paint.setPathEffect(new DashPathEffect(new float[]{3*d,3*d},0));c.drawPath(gaps,paint);paint.setPathEffect(null);}
}
